gM6(){return"\u0422\u0430\u0431\u044b\u043b\u0434\u044b \u043d\u0435 \u0437\u0432\u043e\u043d\u0438\u0442 \u0438 \u043d\u0435 \u043f\u0440\u043e\u0441\u0438\u0442 \u0434\u0435\u043d\u0435\u0433 \u0438\u043b\u0438 \u0434\u0430\u043d\u043d\u044b\u0445. \u041d\u0435 \u0432\u0435\u0440\u044c\u0442\u0435 \u0442\u0430\u043a\u0438\u043c \u0437\u0432\u043e\u043d\u043a\u0430\u043c."},
gM9(){return"\xab\u0412\u0435\u0440\u043d\u0443 \u0442\u043e\u043b\u044c\u043a\u043e \u0437\u0430 \u0434\u0435\u043d\u044c\u0433\u0438\xbb"},
gM8(){return"\u041d\u0435 \u0441\u043e\u0433\u043b\u0430\u0448\u0430\u0439\u0442\u0435\u0441\u044c \u0438 \u043f\u043e\u0436\u0430\u043b\u0443\u0439\u0442\u0435\u0441\u044c \u043d\u0430 \u043e\u0431\u044a\u044f\u0432\u043b\u0435\u043d\u0438\u0435. \u0415\u0441\u043b\u0438 \u0443\u0433\u0440\u043e\u0436\u0430\u044e\u0442 \u2014 \u0437\u0432\u043e\u043d\u0438\u0442\u0435 102."},
